"use client";

import { useState } from "react";
import { RiAddLine, RiAttachment2, RiFocus3Line, RiListCheck3 } from "@remixicon/react";
import { Dropdown, DropdownGroup, DropdownItem, DropdownPopover, DropdownTrigger } from "@/components/base/dropdown/dropdown";
import { cx } from "@/utils/cx";

const ROWS = [
  { icon: RiAttachment2, label: "Files and folders" },
  { icon: RiFocus3Line, label: "Goal", description: "Set a goal for faster results" },
  { icon: RiListCheck3, label: "Plan mode", description: "Manage complex tasks" },
];
const PLUGINS = [
  { id: "documents", label: "Documents", note: "Create and edit documents" },
  { id: "spreadsheets", label: "Spreadsheets", note: "Generate spreadsheets" },
  { id: "presentations", label: "Presentations", note: "Create marketing assets" },
  { id: "codeblocks", label: "Code blocks", note: "Write and edit existing code" },
];

export default function DropdownDemo() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="flex min-h-[420px] w-full items-center justify-center">
      <Dropdown isOpen={isOpen} onOpenChange={setIsOpen}>
        <DropdownTrigger
          aria-label="Add to chat"
          className="flex size-9 shrink-0 items-center justify-center rounded-full bg-background-secondary-default p-2 transition-colors duration-150 ease hover:bg-background-secondary-hover"
        >
          <RiAddLine
            className={cx(
              "size-5 text-foreground-icon-secondary transition-transform duration-200 ease",
              isOpen && "rotate-45",
            )}
            aria-hidden
          />
        </DropdownTrigger>

        <DropdownPopover aria-label="Add to chat" className="w-[361px] p-2" dialogClassName="gap-2">
          <DropdownGroup label="Add">
            {ROWS.map(({ icon: Icon, label, description }) => (
              <DropdownItem key={label} onSelect={() => setIsOpen(false)} className="px-2 py-1.5">
                <Icon className="size-5 shrink-0 text-foreground-icon-secondary" aria-hidden />
                <span className="truncate text-body-medium whitespace-nowrap">
                  <span className="text-text-primary">{label}</span>
                  {description && <span className="ml-1.5 text-text-secondary">{description}</span>}
                </span>
              </DropdownItem>
            ))}
          </DropdownGroup>
          <DropdownGroup label="Plugins">
            {PLUGINS.map((plugin) => (
              <DropdownItem
                key={plugin.id}
                onSelect={() => setIsOpen(false)}
                className="px-2 py-1.5"
              >
                <img
                  src={`/assets/zeus/menu/plugin-${plugin.id}.svg`}
                  alt=""
                  aria-hidden
                  className="size-6 shrink-0"
                />
                <span className="truncate text-body-medium whitespace-nowrap text-text-primary">
                  {plugin.label}
                  <span className="ml-1.5 text-text-secondary">{plugin.note}</span>
                </span>
              </DropdownItem>
            ))}
          </DropdownGroup>
        </DropdownPopover>
      </Dropdown>
    </div>
  );
}

